-- 添加玩家作用域服务,供唐僧内部调用
return function(services: IServiceCollection)
	services:AddHostedService(script.Parent, "IPlayerScopeService")
	services:AddScoped("IPlayerScopeService", script.Parent.PlayerScopeService)
	services:AddScoped("PlayerHostedServiceManager", script.Parent.PlayerHostedServiceManager)
	services:AddScoped("PlayerHostedAsyncServiceManager", script.Parent.PlayerHostedAsyncServiceManager)
	services:AddScoped("ITangSengPlayerProvider", script.Parent.TangSengPlayerProvider)
	services:AddScoped("Player", script.Parent.TangSengPlayer)
	services:AddScoped("SSLogger", script.Parent.SSLogger)

	-- 添加取消令牌提供器
	services:AddSingleton("IPlayerScopeCancellationTokenProvider", script.Parent.PlayerScopeCancellationTokenProvider)
	services:AddScoped("IPlayerScopeCancellationToken", function(serviceProvider: IServiceProvider)
		local cancellationTokenProvider: IPlayerScopeCancellationTokenProvider =
			serviceProvider:GetService("IPlayerScopeCancellationTokenProvider")
		local player: Player = serviceProvider:GetService("Player")
		return cancellationTokenProvider:GetCancellationToken(player.UserId)
	end)

	services:AddServerServices(function(services: IServiceCollection)
		services:AddTangSengDebuggerPlugins(script.Parent.DebuggerPlugins)
	end)
end
